        GGML_TYPE_Q5_K => vec_dot_q5_k_4rows_x86(x, r0, r1, r2, r3, n),
        GGML_TYPE_Q6_K => vec_dot_q6_k_4rows_x86(x, r0, r1, r2, r3, n),
        _ => unreachable!(),
    };
    let scalar = match ttype {
        GGML_TYPE_Q3_K => [
            vec_dot_q3_k(x, r0, n),
            vec_dot_q3_k(x, r1, n),
            vec_dot_q3_k(x, r2, n),
            vec_dot_q3_k(x, r3, n),
