1939	                is += 1;
1940	                for l in 0..16 {
1941	                    let idx = n_outer + j * 32 + 16 + l;
1942	                    let wv = ((q[l + 16] >> shift) & 3) as i8
1943	                        - if (hmask[l + 16] & m) != 0 { 0 } else { 4 };
1944	                    block_sum += xb[idx] * dl2 * wv as f32;
1945	                }
1946	                shift += 2;
