                        let preq = prequantize_activation_q8(&x[..n], n, scratch);
                        run_q8_rows_prequant(
                            xout,
                            mapped,
                            data_offset,
                            row_size,
                            d,
                            |row| unsafe { vec_dot_q8_0_x86_avxvnni_prequant(&preq, row, n) },
