                qwen3next_packed_q_gate = true;
            } else if w.wq[l].rows == q_dim {
                matmul_quantized_with_scratch(
                    &mut s.q[..q_dim],
                    &s.xb[..dim],
                    &w.wq[l],
                    mapped,
                    matmul_scratch,
                )?;
            } else {
                matmul_quantized_rows_with_scratch(
                    &mut s.q[..q_dim],
                    &s.xb[..dim],
                    &w.wq[l],
                    0,
                    q_dim,
                    mapped,
                    matmul_scratch,
                )?;
            }
            if w.wk[l].rows == kv_dim {
                matmul_quantized_with_scratch(
                    &mut s.k[..kv_dim],
                    &s.xb[..dim],
                    &w.wk[l],
                    mapped,
                    matmul_scratch,
                )?;
            } else {
                matmul_quantized_rows_with_scratch(
                    &mut s.k[..kv_dim],
                    &s.xb[..dim],
                    &w.wk[l],
                    0,
                    kv_dim,
                    mapped,
                    matmul_scratch,
                )?;
            }
            if w.wv[l].rows == kv_dim {
                matmul_quantized_with_scratch(
                    &mut s.v[..kv_dim],
                    &s.xb[..dim],
                    &w.wv[l],
                    mapped,
                    matmul_scratch,
                )?;
            } else {
                matmul_quantized_rows_with_scratch(
                    &mut s.v[..kv_dim],
                    &s.xb[..dim],
                    &w.wv[l],
                    0,
                    kv_dim,
                    mapped,
                    matmul_scratch,
                )?;
            }
        } else if p.is_bert_family && w.wq[l].rows == q_dim + 2 * kv_dim {
            // Fused QKV: Q rows [0, q_dim), K rows [q_dim, q_dim+kv_dim), V rows after.
            matmul_quantized_rows_with_scratch(
                &mut s.q[..q_dim],
                &s.xb[..dim],
                &w.wq[l],
                0,
                q_dim,
                mapped,
                matmul_scratch,
            )?;
            matmul_quantized_rows_with_scratch(
                &mut s.k[..kv_dim],
                &s.xb[..dim],
                &w.wq[l],
                q_dim,
                kv_dim,
                mapped,
                matmul_scratch,
            )?;
            matmul_quantized_rows_with_scratch(
                &mut s.v[..kv_dim],
                &s.xb[..dim],
                &w.wq[l],
                q_dim + kv_dim,
                kv_dim,
                mapped,
                matmul_scratch,
            )?;
        } else {
            matmul_quantized_with_scratch(
                &mut s.q[..q_dim],
                &s.xb[..dim],
                &w.wq[l],
                mapped,
                matmul_scratch,
            )?;
            matmul_quantized_with_scratch(
                &mut s.k[..kv_dim],
                &s.xb[..dim],
                &w.wk[l],
                mapped,
                matmul_scratch,
            )?;
            matmul_quantized_with_scratch(
                &mut s.v[..kv_dim],
                &s.xb[..dim],
                &w.wv[l],
                mapped,
                matmul_scratch,
            )?;
        }

        validate_bf16_projection_rows(
            p,
            pos,
            l,
            "attn_k",
            &w.wk[l],
            &s.xb[..dim],
            &s.k[..kv_dim],
            mapped,
        );
        validate_bf16_projection_rows(
            p,
            pos,
            l,
            "attn_v",
            &w.wv[l],
            &s.xb[..dim],
            &s.v[..kv_dim],
            mapped,
        );

        qkv_bias_and_norm(p, s, w, l);

        apply_rope_qk(p, s, l, pos);
        kv_write_token(p, s, l, pos);
        attention_token(p, s, l, pos);

        if qwen3next_packed_q_gate {
            for h in 0..p.n_heads {
                let src_base = h * 2 * head_size + head_size;
                let dst_base = h * head_size;
                sigmoid_mul_inplace(
                    &mut s.xb[dst_base..dst_base + head_size],
                    &s.hb[src_base..src_base + head_size],
                );
            }
            sanitize_finite_inplace(&mut s.xb[..q_dim]);
        }
        matmul_quantized_with_scratch(
            &mut s.xb2[..dim],
            &s.xb[..q_dim],
            &w.wo[l],
            mapped,
            matmul_scratch,
        )?;
        sanitize_finite_inplace(&mut s.xb2[..dim]);
        prof_end(&PROF_ATTN_NS, attn_prof);
    }
    Ok(())
}

fn transformer_inner(
    input: TransformerInput<'_>,
