#[inline]
fn run_q8_rows_prequant<F>(
    xout: &mut [f32],
    mapped: &[u8],
    data_offset: usize,
    row_size: usize,
    d: usize,
    dot: F,
) where
    F: Fn(&[u8]) -> f32 + Sync,
{
    if d >= par_matmul_min_rows() {
