fn kernel_validation_warnings_enabled() -> bool {
    std::env::var("GGUF_KERNEL_VALIDATION_WARNINGS")
        .ok()
        .map(|v| {
            let s = v.trim().to_ascii_lowercase();
            matches!(s.as_str(), "1" | "true" | "yes" | "on")
