#[cfg(target_arch = "x86_64")]
#[inline]
fn validate_legacy_q4_q5_mr4_once_x86(
    x: &[f32],
    mapped: &[u8],
    data_offset: usize,
    row_size: usize,
    n: usize,
    ttype: i32,
) -> bool {
    let status = legacy_q4_q5_mr4_status_x86(ttype);
    match status.load(AtomicOrdering::Relaxed) {
        1 => return true,
        2 => return false,
        _ => {}
    }

    let r0 = &mapped[data_offset..data_offset + row_size];
    let r1 = &mapped[data_offset + row_size..data_offset + 2 * row_size];
    let r2 = &mapped[data_offset + 2 * row_size..data_offset + 3 * row_size];
    let r3 = &mapped[data_offset + 3 * row_size..data_offset + 4 * row_size];

    let mr4 = match ttype {
        GGML_TYPE_Q4_0 => vec_dot_q4_0_4rows_x86(x, r0, r1, r2, r3, n),
        GGML_TYPE_Q4_1 => vec_dot_q4_1_4rows_x86(x, r0, r1, r2, r3, n),
        GGML_TYPE_Q5_0 => vec_dot_q5_0_4rows_x86(x, r0, r1, r2, r3, n),
        GGML_TYPE_Q5_1 => vec_dot_q5_1_4rows_x86(x, r0, r1, r2, r3, n),
        _ => unreachable!(),
    };
    let scalar = match ttype {
        GGML_TYPE_Q4_0 => [
            vec_dot_q4_0(x, r0, n),
            vec_dot_q4_0(x, r1, n),
            vec_dot_q4_0(x, r2, n),
            vec_dot_q4_0(x, r3, n),
        ],
        GGML_TYPE_Q4_1 => [
            vec_dot_q4_1(x, r0, n),
            vec_dot_q4_1(x, r1, n),
            vec_dot_q4_1(x, r2, n),
            vec_dot_q4_1(x, r3, n),
        ],
        GGML_TYPE_Q5_0 => [
            vec_dot_q5_0(x, r0, n),
            vec_dot_q5_0(x, r1, n),
            vec_dot_q5_0(x, r2, n),
            vec_dot_q5_0(x, r3, n),
        ],
        GGML_TYPE_Q5_1 => [
            vec_dot_q5_1(x, r0, n),
            vec_dot_q5_1(x, r1, n),
            vec_dot_q5_1(x, r2, n),
            vec_dot_q5_1(x, r3, n),
        ],
        _ => unreachable!(),
    };

    let mut ok = true;
    for i in 0..4 {
        let a = mr4[i];
        let b = scalar[i];
        let tol = 1e-4f32 * b.abs().max(1.0);
        if (a - b).abs() > tol {
            ok = false;
            break;
        }
    }

    status.store(if ok { 1 } else { 2 }, AtomicOrdering::Relaxed);
    if !ok && kernel_validation_warnings_enabled() {
        eprintln!(
            "Warning: disabling x86_64 legacy Q4/Q5 MR4 kernel for type {} due to validation mismatch",
            ttype
        );
    }
    ok
}

#[cfg(target_arch = "x86_64")]
#[inline]
#[allow(clippy::too_many_arguments)]
fn try_matmul_legacy_q4_q5_mr4_x86(
    xout: &mut [f32],
    x: &[f32],
    mapped: &[u8],
    data_offset: usize,
    row_size: usize,
    n: usize,
    ttype: i32,
) -> bool {
    if !use_x86_qk_mr4() || !use_x86_avx2_fma() {
        return false;
    }
    if !matches!(
        ttype,
        GGML_TYPE_Q4_0 | GGML_TYPE_Q4_1 | GGML_TYPE_Q5_0 | GGML_TYPE_Q5_1
    ) {
        return false;
    }
    if n < QK4_0 || n % QK4_0 != 0 || xout.len() < 4 {
        return false;
    }
    if !validate_legacy_q4_q5_mr4_once_x86(x, mapped, data_offset, row_size, n, ttype) {
        return false;
    }

    let chunk_rows = par_matmul_chunk_rows();
    if xout.len() >= par_matmul_min_rows() {
        xout.par_chunks_mut(chunk_rows)
            .enumerate()
            .for_each(|(chunk_idx, chunk)| {
                let base_row = chunk_idx * chunk_rows;
                matmul_legacy_q4_q5_mr4_chunk_x86(
                    chunk,
                    base_row,
                    x,
                    mapped,
                    data_offset,
                    row_size,
                    n,
                    ttype,
                );
            });
    } else {
        matmul_legacy_q4_q5_mr4_chunk_x86(xout, 0, x, mapped, data_offset, row_size, n, ttype);
    }
    true
}

