        GGML_TYPE_Q5_0 => vec_dot_q5_0_4rows_x86(x, r0, r1, r2, r3, n),
        GGML_TYPE_Q5_1 => vec_dot_q5_1_4rows_x86(x, r0, r1, r2, r3, n),
        _ => unreachable!(),
    };
    let scalar = match ttype {
        GGML_TYPE_Q4_0 => [
            vec_dot_q4_0(x, r0, n),
            vec_dot_q4_0(x, r1, n),
            vec_dot_q4_0(x, r2, n),
            vec_dot_q4_0(x, r3, n),
        ],
        GGML_TYPE_Q4_1 => [
            vec_dot_q4_1(x, r0, n),
            vec_dot_q4_1(x, r1, n),
            vec_dot_q4_1(x, r2, n),
            vec_dot_q4_1(x, r3, n),
        ],
        GGML_TYPE_Q5_0 => [
            vec_dot_q5_0(x, r0, n),
            vec_dot_q5_0(x, r1, n),
            vec_dot_q5_0(x, r2, n),
            vec_dot_q5_0(x, r3, n),
        ],
        GGML_TYPE_Q5_1 => [
            vec_dot_q5_1(x, r0, n),
            vec_dot_q5_1(x, r1, n),
            vec_dot_q5_1(x, r2, n),
            vec_dot_q5_1(x, r3, n),
