unsafe fn load_f16x4_as_f32x4(ptr: *const u8) -> float32x4_t {
    let result: float32x4_t;
    core::arch::asm!(
        "ld1 {{v8.4h}}, [{ptr}]",
        "fcvtl v8.4s, v8.4h",
        ptr = in(reg) ptr,
        out("v8") result,
        options(nostack, pure, readonly),
    );
    result
}

