    let scalar = match ttype {
        GGML_TYPE_Q4_0 => [
            vec_dot_q4_0(x, r0, n),
            vec_dot_q4_0(x, r1, n),
            vec_dot_q4_0(x, r2, n),
            vec_dot_q4_0(x, r3, n),
        ],
        GGML_TYPE_Q4_1 => [
            vec_dot_q4_1(x, r0, n),
            vec_dot_q4_1(x, r1, n),
            vec_dot_q4_1(x, r2, n),
            vec_dot_q4_1(x, r3, n),
        ],
        _ => unreachable!(),
    };

    let mut ok = true;
    for i in 0..4 {
        let a = mr4[i];
        let b = scalar[i];
        let tol = 1e-4f32 * b.abs().max(1.0);
        if (a - b).abs() > tol {
