pub(crate) fn matmul_quantized_batch(
    out: &mut [f32],      // [m × n_rows]
    inp: &[f32],          // [m × n_cols]
    qw: &QuantizedTensor, // [qw.rows × n_cols]
    mapped: &[u8],
    m: usize,
    row_start: usize,
    n_rows: usize,
) -> Result<(), String> {
    let mut dequantized_row = Vec::new();
    matmul_quantized_batch_with_scratch(
