+fn matmul_quantized_batch_tiled_q3_k_exact(
+    out: &mut [f32],
+    inp: &[f32],
+    qw: &QuantizedTensor,
+    mapped: &[u8],
+    m: usize,
+    row_start: usize,
+    n_rows: usize,
+) -> Result<(), String> {
